ALTER TABLE "payments" DROP CONSTRAINT "payments_context_valid";--> statement-breakpoint
ALTER TABLE "payments" ADD CONSTRAINT "payments_context_valid" CHECK (("payments"."type" = 'CHARGE' AND num_nonnulls("payments"."booking_id", "payments"."reservation_id") = 1 AND "payments"."rental_id" IS NULL AND "payments"."source_payment_id" IS NULL AND "payments"."provider" IS NOT NULL AND "payments"."payment_code" IS NOT NULL AND "payments"."provider_payment_id" IS NOT NULL AND "payments"."hold_token_hash" IS NOT NULL) OR ("payments"."type" = 'DEPOSIT_REFUND' AND num_nonnulls("payments"."booking_id", "payments"."reservation_id") <= 1 AND "payments"."rental_id" IS NOT NULL AND "payments"."source_payment_id" IS NOT NULL AND "payments"."provider" IS NULL AND "payments"."payment_code" IS NULL AND "payments"."provider_payment_id" IS NULL AND "payments"."hold_token_hash" IS NULL AND "payments"."status" IN ('REFUND_PENDING', 'REFUNDED')));